import java.io.*;
import java.util.*;

public class Main {
    static class BTreeNode {
        int minDegree;
        List<Integer> keys;
        List<BTreeNode> children;
        boolean isLeaf;

        BTreeNode(int minDegree, boolean isLeaf) {
            this.minDegree = minDegree;
            this.isLeaf = isLeaf;
            this.keys = new ArrayList<>();
            this.children = new ArrayList<>();
        }
    }

    static BTreeNode root = null;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] parts = br.readLine().trim().split("\\s+");
        int n = Integer.parseInt(parts[0]);
        int m = Integer.parseInt(parts[1]);

        int minDegree = (m + 1) / 2;
        root = new BTreeNode(minDegree, true);

        if (n > 0) {
            String[] keysStr = br.readLine().trim().split("\\s+");
            for (int i = 0; i < n; i++) {
                int key = Integer.parseInt(keysStr[i]);
                insert(key, minDegree);
            }
        }

        levelOrderTraversal();
    }

    static void insert(int key, int minDegree) {
        if (root.keys.size() == 2 * minDegree - 1) {
            BTreeNode s = new BTreeNode(minDegree, false);
            s.children.add(root);
            root = s;
            splitChild(s, 0);
        }
        insertNonFull(root, key, minDegree);
    }

    static void insertNonFull(BTreeNode node, int key, int minDegree) {
        int i = node.keys.size() - 1;

        if (node.isLeaf) {
            while (i >= 0 && key < node.keys.get(i)) {
                i--;
            }
            node.keys.add(i + 1, key);
        } else {
            while (i >= 0 && key < node.keys.get(i)) {
                i--;
            }
            i++;

            if (node.children.get(i).keys.size() == 2 * minDegree - 1) {
                splitChild(node, i, minDegree);
                if (key > node.keys.get(i)) {
                    i++;
                }
            }
            insertNonFull(node.children.get(i), key, minDegree);
        }
    }

    static void splitChild(BTreeNode parent, int i, int minDegree) {
        BTreeNode midChild = parent.children.get(i);
        BTreeNode leftChild = new BTreeNode(minDegree, midChild.isLeaf);
        BTreeNode rightChild = new BTreeNode(minDegree, midChild.isLeaf);

        int midKeyIndex = minDegree - 1;
        int midKey = midChild.keys.get(midKeyIndex);

        leftChild.keys.addAll(midChild.keys.subList(0, midKeyIndex));
        rightChild.keys.addAll(midChild.keys.subList(midKeyIndex + 1, midChild.keys.size()));

        if (!midChild.isLeaf) {
            leftChild.children.addAll(midChild.children.subList(0, minDegree));
            rightChild.children.addAll(midChild.children.subList(minDegree, midChild.children.size()));
        }

        parent.keys.add(i, midKey);
        parent.children.add(i, leftChild);
        parent.children.add(i + 1, rightChild);
    }

    static void levelOrderTraversal() {
        if (root == null) return;

        Queue<BTreeNode> queue = new LinkedList<>();
        queue.offer(root);

        while (!queue.isEmpty()) {
            int levelSize = queue.size();
            StringBuilder sb = new StringBuilder();

            for (int i = 0; i < levelSize; i++) {
                BTreeNode node = queue.poll();

                for (int j = 0; j < node.keys.size(); j++) {
                    if (sb.length() > 0) sb.append(' ');
                    sb.append(node.keys.get(j));
                }

                for (BTreeNode child : node.children) {
                    queue.offer(child);
                }
            }

            System.out.println(sb.toString());
        }
    }
}
